// Exnoria - com.contact.reengage
// Branch based on signal_id to handle different re-engagement scenarios

const webhook = $("Webhook").first().json.body;
const contact = $input.first().json;

const { contact_id, signal_id } = webhook;

const firstname = contact.properties?.firstname?.value ?? 'Contact';
const lastname  = contact.properties?.lastname?.value  ?? '';
const email     = contact.properties?.email?.value     ?? '';

let tags = [];
let sequenceEnrollment = null;
let whatsappMessage = null;

// Branch based on signal_id
if (signal_id === 'COM_REL_01') {
  // Unsubscribed contact - enroll in re-engagement sequence
  tags.push('com-reengagement-active');
  sequenceEnrollment = 're-engagement-sequence-id';
} else if (signal_id === 'COM_REL_02') {
  // Low engagement contact - send personalized WhatsApp nudge
  tags.push('com-low-engagement');
  whatsappMessage = `Hi ${firstname}, we've noticed you haven't engaged with our content lately. Here's something tailored just for you!`;
}

const lastReengageAt = new Date(new Date().setUTCHours(0,0,0,0)).getTime();

return [{
  json: {
    contact_id,
    signal_id,
    email,
    firstname,
    lastname,
    tags,
    sequence_enrollment: sequenceEnrollment,
    whatsapp_message: whatsappMessage,
    last_reengage_at: lastReengageAt
  }
}];
